 "content": "def transform(grid):
    """Extend each top-row seed vertically, joining a matching edge marker."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for col, color in enumerate(grid[0]):
        if color == 0:
            continue
        markers = [(r, 0) for r in range(1, h) if grid[r][0] == color]
        markers += [(r, w - 1) for r in range(1, h) if grid[r][w - 1] == color]
        if markers:
            # Matching marker row terminates the vertical ray; its row is
            # filled horizontally from the corresponding edge to the seed.
            r, edge = min(markers, key=lambda item: item[0])
        else:
            r, edge = h - 1, col
        for rr in range(r + 1):
            out[rr][col] = color
        if markers:
            lo, hi = sorted((edge, col))
            for cc in range(lo, hi + 1):
                out[r][cc] = color
    return out
